/* PROLOGUE_STAINED_GLASS_BEGIN */
// Each apse has three separate splayed apertures. The original wall, plinth,
// outer piers and altar footprint are emitted by the base decoration builder.
(() => {
  const panes=/* LANCET_PANES_BEGIN */ ["","",""] /* LANCET_PANES_END */;
  const lights=[
    {x:1.72,width:1.07,height:2.51},
    {x:0,width:1.32,height:3.34},
    {x:-1.72,width:1.07,height:2.51}
  ];
  const sill=1.08;
  // The same measured arch is used for the glass edge, the rear rebate, and
  // both masonry courses. The springing height follows the pointed concept.
  const opening=[[1,0],[1,.70],[.966,.755],[.875,.817],[.72,.875],[.51,.925],[.272,.965],[0,1]];
  const masonry=[opening[0],opening[1],opening[3],opening[5],opening[7]];
  function frame(box,pane) {
    const {x,width,height}=pane;
    const beam=(mat,x1,y1,x2,y2,w,d,z)=>{
      const dx=x2-x1,dy=y2-y1;
      box(mat,w,Math.hypot(dx,dy)+.016,d,E((x1+x2)/2,(y1+y2)/2,z,0,0,-Math.atan2(dx,dy)));
    };
    const half=width/2;
    // Rear rebate and front moulding converge towards the glass. The front nose
    // sits .39 m forward of the painted panes in local shrine space.
    for(const side of [-1,1]){
      for(const [material,offset,thickness,depth,z,rise] of [
        ["dark",.034,.12,.20,.050,.00],
        ["hellEdge",.12,.20,.42,-.130,.085],
        ["hellBasalt",.26,.18,.45,-.11,.17],
        ["hellBronze",.134,.044,.065,-.358,.083]
      ]){
        const w=half+offset,h=height+rise;
        for(let i=1;i<masonry.length;i++){
          const [a,b]=masonry[i-1],[c,d]=masonry[i];
          beam(material,x+side*a*w,sill+b*h,x+side*c*w,sill+d*h,thickness,depth,z);
        }
      }
      box("hellEdge",.32,.17,.43,E(x+side*(half+.14),sill+height*.69,-.15));
      box("hellEdge",.37,.18,.51,E(x+side*(half+.14),sill+.03,-.19));
    }
    box("hellEdge",width+.48,.16,.64,E(x,sill-.11,-.16));
    box("hellBronze",width+.36,.038,.38,E(x,sill-.014,-.17));
  }
  const original=di.hellLancetShrine.build;
  di.hellLancetShrine.build=function(box,...args){
    // Preserve the masonry and altar masses that are shared with other apse passes.
    // The inner jambs, luminous bars, recess backsplash and leadwork are replaced together.
    original.call(this,(mat,w,h,d,matrix)=>{
      if(mat==="hellBasalt" || (mat==="hellEdge" && Math.abs(matrix.elements[12])>=3) ||
          (mat==="hellEdge" && w>7))box(mat,w,h,d,matrix);
    },...args);
    for(const pane of lights)frame(box,pane);
  };

  function glassAtlas() {
    const texture=Z(e0(ctx=>{
      const w=512,h=256,pixels=ctx.createImageData(w,h);
      for(let i=0;i<3;i++){
        const bytes=atob(panes[i]);
        for(let y=0;y<256;y++) for(let x=0;x<128;x++){
          const p=(y*128+x)*2,n=bytes.charCodeAt(p)|(bytes.charCodeAt(p+1)<<8),dst=(y*w+i*128+x)*4;
          pixels.data[dst]=(n>>11)*255/31;
          pixels.data[dst+1]=(n>>5&63)*255/63;
          pixels.data[dst+2]=(n&31)*255/31;
          pixels.data[dst+3]=255;
        }
      }
      ctx.putImageData(pixels,0,0);
    },512,256));
    texture.name="prologueFiguredLancets";
    texture.colorSpace=ha;texture.minFilter=YC;texture.magFilter=i0;texture.generateMipmaps=true;
    return texture;
  }
  function paneGeo(pane,tile) {
    const points=[],uv=[];
    // Viewing the local front from -Z reverses local +X, as it does on the main bridge.
    const vertex=(fraction,v)=> {
      const x=fraction*pane.width*.5;
      points.push(pane.x+x,sill+v*pane.height,-.026-.018*(1-Math.abs(fraction)));
      uv.push((tile*128+1+(1-fraction)*63)/512,(1+v*254)/256);
    };
    for(let i=1;i<opening.length;i++){
      const [a,b]=opening[i-1],[c,d]=opening[i];
      for(const [start,end] of [[-1,0],[0,1]]){
        vertex(start*a,b);vertex(start*c,d);vertex(end*a,b);
        vertex(start*c,d);vertex(end*c,d);vertex(end*a,b);
      }
    }
    const g=new h0();
    g.setAttribute("position",new y0(new Float32Array(points),3));
    g.setAttribute("uv",new y0(new Float32Array(uv),2));g.computeVertexNormals();
    return g;
  }
  const decorate=FJ;
  FJ=function(scene,map){
    decorate.apply(this,arguments);
    if(T.level!==0)return;
    const shrines=map.decor.filter(p=>p.k==="hellLancetShrine");
    if(!shrines.length)return;
    // Transmitted amber light survives the red nave fog, following the native
    // hell-glass response. Dark lead and occluding frame still make deep shadows.
    const material=Z(new $e({map:glassAtlas(),toneMapped:false,fog:false}));
    material.name="hellFiguredGlass";
    const batch=new Map();
    for(const shrine of shrines){
      const cell=Mu(shrine);
      if(LJ(cell.x,cell.z,di.hellLancetShrine.mode))continue;
      const x=(shrine.x+.5)*P,z=(shrine.z+.5)*P;
      const matrix=E(x,ie(x,z),z,0,shrine.r||0,0,shrine.s||1);
      lights.forEach((p,i)=>Yd(batch,material,paneGeo(p,i),matrix));
    }
    const pieces=batch.get(material);
    if(pieces){
      const windows=new pt(Z(BR(pieces)),material);
      windows.name="hellFiguredWindows";
      scene.add(windows);
    }
  };
})();
/* PROLOGUE_STAINED_GLASS_END */
